import json, html
from pathlib import Path
from urllib.parse import quote, urlsplit, urlunsplit, parse_qsl, urlencode

ROOT = Path(__file__).parent
products = json.loads((ROOT/'catalog.json').read_text())['products'] if (ROOT/'catalog.json').exists() else json.loads(Path('/tmp/products.json').read_text())
css = '''
:root{--bg:#f2f0e9;--ink:#151515;--muted:#575750;--line:#cccac2;--accent:#d9ff43;--panel:#e5e3dc}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--bg);color:var(--ink);font-family:Arial,Helvetica,sans-serif}a{color:inherit;text-decoration:none}button,input{font:inherit}a,button,input{ -webkit-tap-highlight-color:transparent}a:focus-visible,button:focus-visible,input:focus-visible,summary:focus-visible{outline:3px solid #9351ff;outline-offset:5px}.skip{position:absolute;left:12px;top:-80px;padding:14px;background:var(--accent);color:#111;z-index:30}.skip:focus{top:10px}.topline{background:var(--ink);color:var(--bg);text-align:center;font-size:10px;letter-spacing:2px;padding:10px}.nav{display:flex;justify-content:space-between;align-items:center;gap:16px;border-bottom:1px solid var(--line);padding:24px 4vw}.brand{font-size:23px;font-weight:950;letter-spacing:-1.2px}.brand span{font-weight:400;font-size:11px;letter-spacing:2px;margin-left:12px}.navlinks{display:flex;gap:28px;align-items:center;font-size:11px;font-weight:700;letter-spacing:1px}.nav a{min-height:44px;display:inline-flex;align-items:center}.storelink{border-bottom:1px solid}.wrap{max-width:1680px;margin:auto;padding:0 4vw}.hero{display:grid;grid-template-columns:1.1fr 1fr;gap:40px;align-items:center;padding:56px 0 64px}.eyebrow{font-family:monospace;font-size:11px;letter-spacing:2px;text-transform:uppercase}.hero h1{font-size:clamp(64px,8.4vw,140px);letter-spacing:-.075em;line-height:.87;font-weight:950;margin:30px 0}.hero h1 em{font-family:Georgia,serif;font-weight:400;letter-spacing:-.065em}.lede{max-width:390px;line-height:1.65;color:var(--muted);font-size:15px}.actions{display:flex;flex-wrap:wrap;gap:12px;margin:28px 0}.btn{display:inline-flex;align-items:center;justify-content:space-between;gap:28px;min-height:52px;background:var(--ink);color:var(--bg);padding:16px 22px;font-size:12px;font-weight:bold}.btn.accent{background:var(--accent);color:#121212}.btn.outline{background:transparent;color:var(--ink);border:1px solid var(--line)}.heroart{position:relative;background:var(--panel);padding:30px;aspect-ratio:1/1.03;overflow:hidden;display:flex;align-items:center;justify-content:center}.heroart:before{content:'HD';position:absolute;font-weight:950;font-size:clamp(140px,28vw,450px);letter-spacing:-.1em;color:var(--line);transform:rotate(-12deg)}.heroart img{width:92%;height:92%;object-fit:contain;position:relative;filter:drop-shadow(0 25px 18px #0002);transform:rotate(-8deg);transition:transform .5s}.heroart:hover img{transform:rotate(-3deg) scale(1.04)}.arttag{position:absolute;bottom:24px;left:24px;right:24px;background:var(--bg);padding:16px;display:flex;justify-content:space-between;gap:14px;font-size:11px;font-weight:700;z-index:2}.badge{position:absolute;right:22px;top:22px;border:1px solid var(--ink);border-radius:50%;height:84px;width:84px;display:grid;place-items:center;text-align:center;font-size:10px;line-height:1.5;transform:rotate(15deg);background:var(--accent);color:#111;z-index:2}.strip{border-top:1px solid var(--ink);border-bottom:1px solid var(--ink);padding:20px 4vw;display:flex;justify-content:space-between;gap:24px;font-size:12px;font-weight:bold;letter-spacing:1px}.collection{padding:72px 0}.sectionhead{display:flex;justify-content:space-between;align-items:end;gap:20px;margin-bottom:28px}h2{font-size:clamp(34px,4.4vw,68px);line-height:1;letter-spacing:-.055em;margin:18px 0} .sectionhead p{color:var(--muted);max-width:330px;font-size:13px;line-height:1.6}.controls{display:flex;align-items:center;justify-content:space-between;gap:20px;border-top:1px solid var(--line);padding:20px 0}.controls label{font-size:11px;letter-spacing:1px}.controls input{background:transparent;border:1px solid var(--line);color:var(--ink);padding:13px 15px;width:min(330px,100%);min-height:46px}.count{font-family:monospace;font-size:12px}.grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:32px 18px}.card[hidden]{display:none}.photo{background:var(--panel);position:relative;aspect-ratio:4/5;display:block;overflow:hidden}.photo img{width:100%;height:100%;object-fit:contain;transition:transform .35s;padding:18px}.photo:hover img{transform:scale(1.055)}.number{position:absolute;top:15px;left:15px;font:10px monospace}.photo .arrow{position:absolute;bottom:14px;right:14px;width:36px;height:36px;background:var(--bg);display:grid;place-items:center;font-size:20px}.card h3{font-size:13px;line-height:1.45;font-weight:600;margin:16px 0 8px;min-height:38px}.card .detail{font-size:11px;color:var(--muted);line-height:1.5}.card .buy{display:inline-flex;align-items:center;min-height:44px;font-size:11px;font-weight:700;text-decoration:underline;text-underline-offset:5px}.empty{padding:30px;border:1px solid var(--line)}.manifesto{background:var(--ink);color:var(--bg);padding:64px 5vw;display:grid;grid-template-columns:1.2fr 1fr;gap:64px;align-items:center}.manifesto h2{font-size:clamp(44px,6vw,90px);margin:22px 0}.manifesto p{line-height:1.7;font-size:15px}.manifesto .btn{background:var(--accent);color:#111}.faq{padding:70px 0;display:grid;grid-template-columns:1fr 1.2fr;gap:60px}details{border-top:1px solid var(--line);padding:18px 0}summary{cursor:pointer;min-height:44px;display:flex;align-items:center;justify-content:space-between;font-size:14px;font-weight:600}summary:after{content:'+'}details[open] summary:after{content:'−'}details p{font-size:14px;color:var(--muted);line-height:1.75}details a{text-decoration:underline}.footer{border-top:1px solid var(--line);padding:30px 4vw}.footerlinks{display:flex;gap:24px;flex-wrap:wrap;font-size:11px}.footerlinks a{min-height:44px;display:flex;align-items:center}.wordmark{font-size:clamp(42px,12.4vw,200px);letter-spacing:-.075em;font-weight:950;white-space:nowrap;margin:25px 0 0;line-height:1}.smallprint{font-size:10px;color:var(--muted);margin-top:25px;line-height:1.6}.cloud{--bg:#101112;--ink:#f2f0e9;--muted:#b2b2b6;--line:#393a3f;--panel:#e4e2e8;--accent:#c7b5ff}.cloud .topline{background:var(--accent);color:#111}.cloud .heroart:before{color:#b9b4c8}.cloud .heroart{border-radius:48% 48% 0 0}.cloud .hero h1{font-family:Georgia,serif;font-weight:400;letter-spacing:-.07em}.cloud .hero h1 em{color:var(--accent)}.cloud .heroart .arttag{background:#141416;color:#fff}.cloud .grid{grid-template-columns:repeat(3,minmax(0,1fr))}.cloud .photo{aspect-ratio:1/1.15}.cloud .manifesto{background:#24212d;color:#f2f0e9}.cloud .number{color:#25232b}.cloud .badge{border-color:#111;right:16%;top:12%}.cloud .heroart{isolation:isolate}.cloud .heroart img{transform:rotate(5deg)}@media(max-width:900px){.grid{grid-template-columns:repeat(3,minmax(0,1fr))}.navlinks{gap:18px}.hero{gap:24px}.hero h1{font-size:10vw}.heroart{padding:12px}.badge{height:66px;width:66px}.manifesto{gap:24px}.faq{gap:30px}}@media(max-width:620px){.brand{font-size:20px}.brand span{display:none}.nav{padding:14px 5vw}.navlinks a:first-child{display:none}.navlinks{gap:18px;font-size:10px}.wrap{padding:0 5vw}.hero{grid-template-columns:1fr;padding:32px 0;gap:26px}.hero h1{font-size:21vw;margin:24px 0}.heroart{aspect-ratio:1.05}.lede{max-width:95%;font-size:14px}.badge{height:76px;width:76px}.strip{font-size:9px;gap:12px;padding:18px 5vw;flex-wrap:wrap}.strip span:last-child{display:none}.collection{padding:42px 0}.sectionhead{display:block}.sectionhead p{max-width:100%}.controls{flex-wrap:wrap;gap:12px}.controls input{width:100%}.controls label{width:100%}.grid,.cloud .grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:26px 12px}.card h3{font-size:12px}.photo img{padding:8px}.number{top:10px;left:10px}.manifesto{grid-template-columns:1fr;padding:38px 6vw;gap:10px}.faq{grid-template-columns:1fr;gap:10px;padding:40px 0}.footerlinks{gap:15px}.arttag{bottom:18px;left:18px;right:18px}.wordmark{font-size:12.2vw}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}*,*:before,*:after{transition:none!important;animation:none!important}}
'''
js = '''const input=document.querySelector('#search');const cards=[...document.querySelectorAll('.card')];const count=document.querySelector('#count');input.addEventListener('input',()=>{const q=input.value.toLowerCase().trim();let n=0;cards.forEach(card=>{card.hidden=!card.dataset.name.includes(q);if(!card.hidden)n++});count.textContent=n+' pieces';document.querySelector('#empty').hidden=n>0;});'''

def build(kind):
    domain='hustlerdior.'+kind
    out=ROOT/kind;out.mkdir(parents=True,exist_ok=True)
    source=kind+'_landing'
    def link(url):
        u=urlsplit(url)
        query=urlencode(parse_qsl(u.query)+[('utm_source',source),('utm_medium','referral'),('utm_campaign','concrete_edit')])
        return html.escape(urlunsplit((u.scheme,u.netloc,u.path,query,u.fragment)),quote=True)
    def image(p,w=640):return html.escape('https://hustlerdior.com/_next/image?url='+quote(p['image'],safe='')+'&w='+str(w)+'&q=75',quote=True)
    selected=products if kind=='shop' else [products[i] for i in [1,0,3,7,4,2,5,8,11]]
    hero=products[1] if kind=='shop' else products[7]
    title='The Concrete Shop' if kind=='shop' else 'The Cloud Edit'
    headline='WEAR YOUR<br>OWN <em>STORY.</em>' if kind=='shop' else 'Above the<br><em>ordinary.</em>'
    intro='Statement graphics. Everyday rotation. Explore independent streetwear from the Hustler Dior collection.' if kind=='shop' else 'A different perspective on your everyday wardrobe. Discover graphic tees, oversized silhouettes, and pieces with a point of view.'
    cards=''.join(f'''<article class="card" data-name="{html.escape(p['name'].lower(),quote=True)}"><a class="photo" href="{link(p['url'])}" aria-label="View {html.escape(p['name'],quote=True)}"><span class="number" aria-hidden="true">HD / {i+1:02}</span><img src="{image(p)}" alt="{html.escape(p['name'],quote=True)}" loading="lazy" decoding="async" width="640" height="800"><span class="arrow" aria-hidden="true">↗</span></a><h3><a href="{link(p['url'])}">{html.escape(p['name'])}</a></h3><div class="detail">Current price & sizes on HustlerDior.com</div><a class="buy" href="{link(p['url'])}">VIEW PIECE ↗</a></article>''' for i,p in enumerate(selected))
    description=intro+' Browse the edit and shop directly at HustlerDior.com.'
    schema={'@context':'https://schema.org','@type':'CollectionPage','name':'Hustler Dior — '+title,'url':'https://'+domain+'/','description':description,'mainEntity':{'@type':'ItemList','itemListElement':[{'@type':'ListItem','position':i+1,'name':p['name'],'url':p['url']} for i,p in enumerate(selected)]}}
    doc=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="{'#101112' if kind=='cloud' else '#f2f0e9'}"><title>Hustler Dior — {title} | Independent Streetwear</title><meta name="description" content="{html.escape(description,quote=True)}"><link rel="canonical" href="https://{domain}/"><meta property="og:title" content="Hustler Dior — {title}"><meta property="og:description" content="{html.escape(description,quote=True)}"><meta property="og:url" content="https://{domain}/"><meta property="og:type" content="website"><meta property="og:image" content="{html.escape(hero['image'],quote=True)}"><meta name="twitter:card" content="summary_large_image"><link rel="preconnect" href="https://hustlerdior.com"><link rel="stylesheet" href="styles.css"><script type="application/ld+json">{json.dumps(schema).replace('<','\\u003c')}</script><script src="app.js" defer></script></head><body class="{kind}"><a class="skip" href="#main">Skip to content</a><div class="topline">INDEPENDENT STREETWEAR / UNFILTERED EXPRESSION</div><header class="nav"><a class="brand" href="/">HUSTLER DIOR<span> / {kind.upper()}</span></a><nav class="navlinks" aria-label="Main navigation"><a href="#collection">THE EDIT</a><a href="#questions">GOOD TO KNOW</a><a class="storelink" href="{link('https://hustlerdior.com/')}">MAIN STORE ↗</a></nav></header><main id="main"><div class="wrap"><section class="hero" aria-labelledby="headline"><div><div class="eyebrow">HD / 001 — {title}</div><h1 id="headline">{headline}</h1><p class="lede">{intro}</p><div class="actions"><a class="btn accent" href="#collection">EXPLORE THE EDIT <span>↘</span></a><a class="btn outline" href="{link('https://hustlerdior.com/#collection')}">SHOP ALL ↗</a></div><div class="eyebrow">Your world. Your wardrobe. Your rules.</div></div><a class="heroart" href="{link(hero['url'])}" aria-label="Shop {html.escape(hero['name'],quote=True)}"><span class="badge" aria-hidden="true">INDEPENDENT<br>BY DESIGN<br>✳</span><img src="{image(hero,828)}" width="828" height="828" alt="{html.escape(hero['name'],quote=True)}" fetchpriority="high"><span class="arttag"><span>{'757 / VIRGINIA BEACH LEGENDS' if kind=='shop' else 'THE OVERSIZED EDIT / MR. ROGERS'}</span><span>VIEW PIECE ↗</span></span></a></section></div><div class="strip"><span>✳ ORIGINAL EXPRESSION</span><span>✳ FIND YOUR ROTATION</span><span>✳ HUSTLERDIOR.COM</span></div><div class="wrap"><section id="collection" class="collection" aria-labelledby="collection-title"><div class="sectionhead"><div><div class="eyebrow">{'YOUR NEXT SIGNATURE PIECE' if kind=='shop' else 'A CURATED POINT OF VIEW'}</div><h2 id="collection-title">{'THE DAILY ROTATION.' if kind=='shop' else 'Objects of expression.'}</h2></div><p>Explore the edit, then choose your size and color on HustlerDior.com. Current prices and availability are shown on each product page.</p></div><div class="controls"><span class="count" id="count" role="status">{len(selected)} pieces</span><label for="search">FIND YOUR PIECE <input type="search" id="search" placeholder="Search the edit…" autocomplete="off"></label></div><div class="grid">{cards}</div><p id="empty" class="empty" hidden>No pieces match. Try another search or <a href="{link('https://hustlerdior.com/#collection')}">browse the full collection ↗</a>.</p></section><section class="manifesto"><div><div class="eyebrow">THE HUSTLER DIOR POINT OF VIEW</div><h2>MADE TO<br>MAKE NOISE.</h2></div><div><p>For the creators, the risk-takers, and the ones building something of their own. Find a graphic that says something. Make it part of your everyday.</p><a class="btn" href="{link('https://hustlerdior.com/#collection')}">FIND YOUR EXPRESSION ↗</a></div></section><section id="questions" class="faq"><div><div class="eyebrow">BEFORE YOU CHOOSE</div><h2>GOOD TO KNOW.</h2><p class="lede">The details that help you find your fit.</p></div><div><details><summary>Where do I buy these pieces?</summary><p>Every product link takes you to the matching product on <a href="{link('https://hustlerdior.com/')}">HustlerDior.com</a>, where you can review the current price, select options, and place your order.</p></details><details><summary>How do I choose my size?</summary><p>Check the measurements on the product page and compare them with a piece you already own. Start with the <a href="{link('https://hustlerdior.com/fit-guide')}">fit guide</a> for sizing help.</p></details><details><summary>What about shipping and returns?</summary><p>Review the store’s <a href="{link('https://hustlerdior.com/shipping')}">shipping information</a> and <a href="{link('https://hustlerdior.com/returns')}">returns policy</a> before ordering. The main store provides the applicable order details.</p></details><details><summary>Is this the entire collection?</summary><p>This is a selection from Hustler Dior. Visit the <a href="{link('https://hustlerdior.com/#collection')}">full collection</a> for more styles and current availability.</p></details></div></section></div></main><footer class="footer"><div class="footerlinks"><a href="{link('https://hustlerdior.com/about')}">ABOUT</a><a href="{link('https://hustlerdior.com/fit-guide')}">FIT GUIDE</a><a href="{link('https://hustlerdior.com/contact')}">CONTACT</a><a href="{link('https://hustlerdior.com/privacy')}">PRIVACY</a><a href="{link('https://hustlerdior.com/terms')}">TERMS</a><a href="#main">BACK TO TOP ↑</a></div><div class="wordmark" aria-hidden="true">HUSTLER DIOR</div><div class="smallprint">© 2026 Hustler Dior. {domain.upper()} / Purchases handled at HustlerDior.com. Independent brand; not affiliated with Christian Dior.</div></footer></body></html>'''
    (out/'index.html').write_text(doc)
    (out/'styles.css').write_text(css)
    (out/'app.js').write_text(js)
    (out/'robots.txt').write_text('User-agent: *\nAllow: /\nSitemap: https://'+domain+'/sitemap.xml\n')
    (out/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9"><url><loc>https://'+domain+'/</loc></url></urlset>')

for kind in ['shop','cloud']:build(kind)
(ROOT/'catalog.json').write_text(json.dumps({'source':'https://hustlerdior.com/','captured':'2026-11-04','products':products},indent=2))
print('Built shop and cloud landing pages')
